package io.knowledgebrain.planning;
import java.util.*;import java.time.*;import java.sql.Timestamp;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import tools.jackson.databind.json.JsonMapper;import io.knowledgebrain.contracts.planning.task.v1.*;
/** Planning owns tasks, immutable revisions and their local transactional Outbox. */
final class TaskStore {
 record Input(String title,String description,String status,String dueDate,UUID goalId){}
 record Task(UUID taskId,UUID spaceId,String visibility,String state,long version,String title,String description,String status,String dueDate,UUID goalId,String createdAt,String updatedAt){}
 record Creation(Task task,boolean replay){}
 record Summary(UUID taskId,String title,String status,String dueDate,UUID goalId,long version,String updatedAt,String state){}
 record Page(UUID spaceId,String state,String status,String goalFilter,List<Summary> items,UUID nextAfter){}
 record Revision(UUID revisionId,UUID taskId,long version,UUID actorId,String occurredAt,Task snapshot){}
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final Clock clock;private final UuidV7 ids;private final JsonMapper json=JsonMapper.builder().build();
 TaskStore(DataSource source,Clock clock){jdbc=new JdbcTemplate(source);tx=new TransactionTemplate(new DataSourceTransactionManager(source));tx.setTimeout(15);this.clock=clock;ids=new UuidV7(clock);}
 static ResponseStatusException missing(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Task unavailable");}
 private String hash(Input input){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(input)));}catch(Exception e){throw new IllegalStateException(e);}}
 Creation create(UUID space,UUID actor,String key,Input input,String trace){TaskRules.id(space);TaskRules.id(actor);TaskRules.trace(trace);TaskRules.input(input);if(key==null||!key.matches("[0-9a-f]{32}"))throw TaskRules.bad();String hash=hash(input);return tx.execute(s->{var id=ids.next();var now=clock.instant();int inserted=jdbc.update("INSERT INTO task(task_id,space_id,visibility,state,version,title,description,status,due_date,goal_id,created_at,updated_at,request_key,request_hash) VALUES (?,?,'PRIVATE','ACTIVE',1,?,?,?,?,?,?,?,?,?) ON CONFLICT(space_id,request_key) DO NOTHING",id,space,input.title(),input.description(),input.status(),input.dueDate()==null?null:LocalDate.parse(input.dueDate()),input.goalId(),Timestamp.from(now),Timestamp.from(now),key,hash);if(inserted==0){var rows=jdbc.query("SELECT g.request_hash,r.snapshot::text FROM task g JOIN task_revision r ON r.task_id=g.task_id AND r.version=1 WHERE g.space_id=? AND g.request_key=?",(rs,n)->Map.entry(rs.getString(1),rs.getString(2)),space,key);if(rows.size()!=1)throw new IllegalStateException("Original task creation missing");if(!MessageDigest.isEqual(hash.getBytes(StandardCharsets.US_ASCII),rows.getFirst().getKey().getBytes(StandardCharsets.US_ASCII)))throw new ResponseStatusException(HttpStatus.CONFLICT,"Creation key already represents different task input");return new Creation(json.readValue(rows.getFirst().getValue(),Task.class),true);}checkGoal(space,input.goalId());var value=new Task(id,space,"PRIVATE","ACTIVE",1,input.title(),input.description(),input.status(),input.dueDate(),input.goalId(),now.toString(),now.toString());revision(value,actor,trace,"TaskCreated");return new Creation(value,false);});}
 private Task decode(String raw,UUID space,UUID id,long version,String state){if(raw==null)throw new IllegalStateException("Task revision missing");var value=json.readValue(raw,Task.class);if(!value.spaceId().equals(space)||!value.taskId().equals(id)||value.version()!=version||!value.state().equals(state)||!value.visibility().equals("PRIVATE"))throw new IllegalStateException("Task revision mismatch");return value;}
 private Task current(UUID space,UUID id,boolean lock,boolean active){TaskRules.id(space);TaskRules.id(id);if(lock){record Head(long version,String state){}var heads=jdbc.query("SELECT version,state FROM task WHERE space_id=? AND task_id=? FOR UPDATE",(rs,n)->new Head(rs.getLong(1),rs.getString(2)),space,id);if(heads.isEmpty()||active&&!heads.getFirst().state().equals("ACTIVE"))throw missing();var h=heads.getFirst();String raw=jdbc.queryForObject("SELECT snapshot::text FROM task_revision WHERE task_id=? AND version=?",String.class,id,h.version());return decode(raw,space,id,h.version(),h.state());}var rows=jdbc.query("SELECT g.version,g.state,r.snapshot::text FROM task g LEFT JOIN task_revision r ON r.task_id=g.task_id AND r.version=g.version WHERE g.space_id=? AND g.task_id=?",(rs,n)->decode(rs.getString(3),space,id,rs.getLong(1),rs.getString(2)),space,id);if(rows.isEmpty()||active&&!rows.getFirst().state().equals("ACTIVE"))throw missing();return rows.getFirst();}
 Task get(UUID space,UUID id){return current(space,id,false,true);}
 Task change(UUID space,UUID id,UUID actor,long expected,Input input,boolean retire,String trace){TaskRules.id(actor);TaskRules.trace(trace);if(expected<1)throw TaskRules.bad();if(!retire)TaskRules.input(input);return tx.execute(s->{var prior=current(space,id,true,true);if(prior.version()!=expected)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Task changed; inspect latest before saving");if(!retire&&new Input(prior.title(),prior.description(),prior.status(),prior.dueDate(),prior.goalId()).equals(input))return prior;if(!retire&&!Objects.equals(prior.goalId(),input.goalId()))checkGoal(space,input.goalId());var value=new Task(id,space,"PRIVATE",retire?"RETIRED":"ACTIVE",Math.addExact(prior.version(),1),retire?prior.title():input.title(),retire?prior.description():input.description(),retire?prior.status():input.status(),retire?prior.dueDate():input.dueDate(),retire?prior.goalId():input.goalId(),prior.createdAt(),clock.instant().toString());jdbc.update("UPDATE task SET title=?,description=?,status=?,due_date=?,goal_id=?,state=?,version=?,updated_at=? WHERE task_id=?",value.title(),value.description(),value.status(),value.dueDate()==null?null:LocalDate.parse(value.dueDate()),value.goalId(),value.state(),value.version(),Timestamp.from(Instant.parse(value.updatedAt())),id);revision(value,actor,trace,retire?"TaskRetired":"TaskUpdated");return value;});}
 private void checkGoal(UUID space,UUID goal){if(goal==null)return;var rows=jdbc.query("SELECT state FROM goal WHERE space_id=? AND goal_id=? FOR UPDATE",(rs,n)->rs.getString(1),space,goal);if(rows.isEmpty()||!rows.getFirst().equals("ACTIVE"))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Goal unavailable for task link");}
 Page list(UUID space,String state,String status,String goalFilter,UUID after,int limit){
  TaskRules.id(space);if(after!=null)TaskRules.id(after);if(!Set.of("ACTIVE","RETIRED").contains(state)||status==null||!status.equals("ALL")&&!TaskRules.STATUSES.contains(status)||limit<1||limit>100||goalFilter==null)throw TaskRules.bad();UUID goal=null;if(!Set.of("ALL","NONE").contains(goalFilter))goal=TaskRules.id(goalFilter);
  var args=new ArrayList<Object>();args.add(space);args.add(state);String sql="SELECT task_id,title,status,due_date,goal_id,version,updated_at,state FROM task WHERE space_id=? AND state=?";
  if(!status.equals("ALL")){sql+=" AND status=?";args.add(status);}if(goalFilter.equals("NONE"))sql+=" AND goal_id IS NULL";else if(goal!=null){sql+=" AND goal_id=?";args.add(goal);}if(after!=null){sql+=" AND task_id>?";args.add(after);}sql+=" ORDER BY task_id LIMIT ?";args.add(limit+1);
  var rows=jdbc.query(sql,(rs,n)->new Summary(rs.getObject(1,UUID.class),rs.getString(2),rs.getString(3),rs.getObject(4,LocalDate.class)==null?null:rs.getObject(4,LocalDate.class).toString(),rs.getObject(5,UUID.class),rs.getLong(6),rs.getTimestamp(7).toInstant().toString(),rs.getString(8)),args.toArray());var page=List.copyOf(rows.subList(0,Math.min(rows.size(),limit)));return new Page(space,state,status,goalFilter,page,rows.size()>limit?page.getLast().taskId():null);
 }
 List<Revision> history(UUID space,UUID id,long before,int limit){current(space,id,false,false);if(before<1||limit<1||limit>10)throw TaskRules.bad();return jdbc.query("SELECT revision_id,task_id,version,actor_id,occurred_at,snapshot::text FROM task_revision WHERE task_id=? AND version<? ORDER BY version DESC LIMIT ?",(rs,n)->new Revision(rs.getObject(1,UUID.class),rs.getObject(2,UUID.class),rs.getLong(3),rs.getObject(4,UUID.class),rs.getTimestamp(5).toInstant().toString(),json.readValue(rs.getString(6),Task.class)),id,before,limit);}
 private void revision(Task value,UUID actor,String trace,String type){UUID revision=ids.next(),event=ids.next();var now=Instant.parse(value.updatedAt());jdbc.update("INSERT INTO task_revision VALUES (?,?,?,?,?,?::jsonb)",revision,value.taskId(),value.version(),actor,Timestamp.from(now),json.writeValueAsString(value));var payload=TaskChangedPayloadV1.newBuilder().setTaskId(value.taskId().toString()).setRevisionId(revision.toString()).setVersion(value.version()).setVisibility("PRIVATE").setState(value.state()).setTitle(value.title()).setDescription(value.description()).setStatus(value.status()).setDueDate(value.dueDate()==null?"":value.dueDate()).setGoalId(value.goalId()==null?"":value.goalId().toString()).setCreatedAt(value.createdAt()).setUpdatedAt(value.updatedAt()).build();var envelope=TaskEventEnvelopeV1.newBuilder().setEventId(event.toString()).setEventType(type).setEventVersion(1).setOccurredAtEpochMillis(now.toEpochMilli()).setProducer("planning-service").setAggregateType("Task").setAggregateId(value.taskId().toString()).setSpaceId(value.spaceId().toString()).setActorId(actor.toString()).setTraceId(trace).setPayload(payload.toByteString()).build();jdbc.update("INSERT INTO outbox_event VALUES (?,'task',?,?,?,?, 'planning','task-events','1',?)",event,value.taskId(),type,Timestamp.from(now),trace,envelope.toByteArray());}
}
